FINDER='''<section class="block" id="jn-finder" data-icon="compass" data-label="What applies to you"><div class="sechead"><span class="eyebrow">Your circumstances</span><h2>Find what applies to you</h2><p>Tick anything that describes you to see the sourced points that matter most. This is general information, not advice on your own case: for immigration questions, use a regulated adviser.</p></div><fieldset class="jnfs"><legend class="vh">Your circumstances</legend><div class="jnopts" id="jnFinderOpts"></div></fieldset><div id="jnFinderOut" aria-live="polite"></div></section>'''
PREP='''<section class="block" id="jn-prep" data-icon="tool" data-label="Preparation checklist"><div class="sechead"><span class="eyebrow">Before you apply and interview</span><h2>Preparation checklist</h2><p>Work through these steps. Each links to the sourced points behind it.</p></div><ol class="jnprep" id="jnPrepList"></ol><p class="mono muted" id="jnPrepN" aria-live="polite"></p><button type="button" class="btn" id="jnPrepReset">Clear my ticks</button></section>'''
ASKS='''<section class="block" id="jn-asks" data-icon="people" data-label="What people ask"><div class="sechead"><span class="eyebrow">At careers fairs and in public forums</span><h2>What people ask about joining government</h2><p>The questions people ask most often about government jobs, each with where to find the answer on this page. They are taken from published event write-ups, official question-and-answer forums, guidance and research. Questions put to stands at particular events are not published, so none is attributed to a named event or person.</p></div><div class="grid g2" id="jnAsksList"></div></section>'''
TRACKER='''<section class="block" id="jn-tracker" data-icon="calendar" data-label="Your application tracker"><div class="sechead"><span class="eyebrow">Do it yourself</span><h2>Your application tracker</h2><p>Record each application, its dates and its feedback. Everything stays in this browser: nothing is sent anywhere. Do not store passwords here. Download a copy for a spreadsheet, or add every date to your calendar with a reminder the day before. The hub recommends no particular app: a spreadsheet, a calendar, a notes app or this page all work.</p></div><div id="trkApp"></div></section>'''
LADDER='''<section class="block" id="ft-ladder" data-icon="ladder" data-label="The escalation ladder"><div class="sechead"><span class="eyebrow">Step by step</span><h2>The escalation ladder</h2><p>Each step is one rung up. You can skip a rung if the situation is serious, and the tribunal time limit keeps running throughout, so do not wait for one step to finish before checking the next deadline.</p></div><div id="ftLadders"></div></section>'''
MOSCOW='''<section class="block" id="ld-moscow" data-icon="flag" data-label="What to do, in priority order"><div class="sechead"><span class="eyebrow">Must, Should, Could, Won't</span><h2>What to do in 2026-27 and 2027-28, in priority order</h2><p>Actions for organisations, leaders and sponsors, allies, and communities and networks, each with its basis and source. Choose who you are to filter the list.</p></div><div id="tgMoscow"></div></section>'''
PAF='''<section class="block" id="yp-finder" data-icon="compass" data-label="Find a way to take part"><div class="sechead"><span class="eyebrow">By stage of life and nation</span><h2>Find a way to take part</h2><p>Choose your stage of life and where you live. Each option shows the youngest age it is open to and links to its source.</p></div><div id="ypFinder"></div></section>'''
def apply(s):
    def after(anchor,html):
        a=s.index(anchor);b=s.index('</section>',a)+len('</section>');return s[:b]+'\n  '+html+s[b:]
    s=after('<section class="block" id="jn-jnroutes"',FINDER)
    s=after('<section class="block" id="jn-jninterview"',PREP)
    s=after('<section class="block" id="jn-trtools"',TRACKER)
    a=s.index('<section class="block" id="jn-jnbarriers"');s=s[:a]+ASKS+'\n  '+s[a:]
    if '<section class="block" id="ft-rdrecruit"' in s: s=after('<section class="block" id="ft-rdrecruit"',LADDER)
    if '<section class="block" id="tg-tgally"' in s: s=after('<section class="block" id="tg-tgally"',MOSCOW)
    if '<section class="block" id="yp-pavoice"' in s: s=after('<section class="block" id="yp-pavoice"',PAF)
    return s
